	/** Shows whichever view is chosen, including the board's own pages. */
	private void showView()
	{
		int chosen = viewSelect.getSelectedIndex();
		JPanel view;

		if (chosen == 1)
		{
			view = weekTab;
			drawWeek();
		}
		else if (chosen == 2)
		{
			view = eventTab;
		}
		else if (chosen == 3)
		{
			view = statsTab;
			if (!statsAsked)
			{
				askGained(metric);
			}
		}
		else if (chosen == 4)
		{
			view = activityTab;
		}
		else if (chosen >= VIEWS.length)
		{
			drawBoardPage(chosen - VIEWS.length);
			view = pageTab;
		}
		else
		{
			view = homeTab;
		}

		display.removeAll();
		display.add(view, BorderLayout.NORTH);
		display.revalidate();
		display.repaint();
	}

