	/** An item's name and its two prices, as read on the client thread. */
	static final class Facts
	{
		private final String name;

		/*
		 * Prices are long, not int.
		 *
		 * RuneLite widened getItemPrice in 1.13.0, and rightly: a stack can be
		 * worth more than an int holds. Held the same way here so nothing is
		 * quietly truncated on the way through.
		 */
		private final long ge;
		private final long ha;

		Facts(String name, long ge, long ha)
		{
			this.name = name;
			this.ge = ge;
			this.ha = ha;
		}
	}

	/** What each item is called and worth, once the plugin has looked it up. */
	void setFacts(Map<Integer, Facts> known)
	{
		// Only worth a redraw if it taught us something. Otherwise every
		// drawing of the tab caused a second one straight after it.
		boolean better = known.size() > facts.size();
		facts = known;
		if (better)
		{
			// Through the same wait as a drop, rather than straight away. Facts
			// turn up moments after the drop that wanted them, and redrawing
			// for each meant two rebuilds of the tab for every one kill.
			SwingUtilities.invokeLater(this::redrawSoon);
		}
	}

